  const ::flatbuffers::Vector<::flatbuffers::Offset<PMMModuleEntry>> *MODULES() const {
    return GetPointer<const ::flatbuffers::Vector<::flatbuffers::Offset<PMMModuleEntry>> *>(VT_MODULES);
  }
