  auto _PROVIDER_NAME = _o->PROVIDER_NAME.empty() ? 0 : _fbb.CreateString(_o->PROVIDER_NAME);
  auto _DESCRIPTION = _o->DESCRIPTION.empty() ? 0 : _fbb.CreateString(_o->DESCRIPTION);
  auto _EPOCH = _o->EPOCH;
  auto _TRUST = _o->TRUST ? CreatePMMTrustAnchor(_fbb, _o->TRUST.get(), _rehasher) : 0;
