  auto _CANONICAL_URL = _o->CANONICAL_URL.empty() ? 0 : _fbb.CreateString(_o->CANONICAL_URL);
  auto _CREATED_AT = _o->CREATED_AT.empty() ? 0 : _fbb.CreateString(_o->CREATED_AT);
  auto _UPDATED_AT = _o->UPDATED_AT.empty() ? 0 : _fbb.CreateString(_o->UPDATED_AT);
  auto _EXPIRES_AT = _o->EXPIRES_AT.empty() ? 0 : _fbb.CreateString(_o->EXPIRES_AT);
  auto _SIGNATURE = _o->SIGNATURE.size() ? _fbb.CreateVector(_o->SIGNATURE) : 0;
  auto _SIGNED_STATEMENT = _o->SIGNED_STATEMENT.empty() ? 0 : _fbb.CreateString(_o->SIGNED_STATEMENT);
  return CreatePMM(
      _fbb,
      _PROVIDER_DOMAIN,
      _PROVIDER_NAME,
      _DESCRIPTION,
      _EPOCH,
      _TRUST,
      _MODULES,
      _CANONICAL_URL,
      _CREATED_AT,
      _UPDATED_AT,
      _EXPIRES_AT,
      _SIGNATURE,
      _SIGNED_STATEMENT);
