inline const PMM *GetPMM(const void *buf) {
  return ::flatbuffers::GetRoot<PMM>(buf);
}

inline const PMM *GetSizePrefixedPMM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<PMM>(buf);
}

inline const char *PMMIdentifier() {
  return "$PMM";
}

inline bool PMMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PMMIdentifier());
}

inline bool SizePrefixedPMMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PMMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyPMMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<PMM>(PMMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedPMMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<PMM>(PMMIdentifier());
}

inline void FinishPMMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PMM> root) {
  fbb.Finish(root, PMMIdentifier());
}

inline void FinishSizePrefixedPMMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PMM> root) {
  fbb.FinishSizePrefixed(root, PMMIdentifier());
}

inline std::unique_ptr<PMMT> UnPackPMM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PMMT>(GetPMM(buf)->UnPack(res));
}

inline std::unique_ptr<PMMT> UnPackSizePrefixedPMM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PMMT>(GetSizePrefixedPMM(buf)->UnPack(res));
}

